solution.javascript:
function isValidSudoku(board) {
  const rows = Array(9).fill(null).map(() => new Set());
  const cols = Array(9).fill(null).map(() => new Set());
  const boxes = Array(9).fill(null).map(() => new Set());
  for (let r = 0; r < 9; r++) {
    for (let c = 0; c < 9; c++) {
      const ch = board[r][c];
      if (ch === '.') continue;
      const b = Math.floor(r/3)*3 + Math.floor(c/3);
      if (rows[r].has(ch) || cols[c].has(ch) || boxes[b].has(ch)) return false;
      rows[r].add(ch); cols[c].add(ch); boxes[b].add(ch);
    }
  }
  return true;
}

solution.cpp:
bool isValidSudoku(vector<vector<char>>& board) {
    vector<unordered_set<char>> rows(9), cols(9), boxes(9);
    for (int r = 0; r < 9; r++)
        for (int c = 0; c < 9; c++) {
            char ch = board[r][c];
            if (ch == '.') continue;
            int b = (r/3)*3 + c/3;
            if (rows[r].count(ch) || cols[c].count(ch) || boxes[b].count(ch)) return false;
            rows[r].insert(ch); cols[c].insert(ch); boxes[b].insert(ch);
        }
    return true;
}
